# PUT /api/sheets/{sheetId}/rates/{grade} — set a grade's rate, a percent with two decimals, from
# an optional from-date (none: from the beginning of time) through an optional to-date (none: no
# end), replacing any it had for that from-date. A grade other than A, B or C, a rate that is not a
# number 0.00 or more with up to two decimals, a from- or to-date that is not yyyy-MM-dd, or a
# to-date before the from-date, is a 400 and writes nothing. Responds with the
# rate as stored.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.rate.RecordRateSet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Collection;
import java.util.regex.Pattern;
import net.officefloor.hq.app.grade.GradeRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the grade is one of the sheet's grades; the rate a percent 0.00 or more with up to two decimals;
 *  the from-date and to-date blank (none) or a date yyyy-MM-dd, the to-date not before the from-date. */
public class ValidateRate {
    private static final Pattern RATE = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("grade") String grade, @RequestBody RateRequest request,
            GradeRepository grades, Out<RateValues> values)
            throws InvalidRateException {
        values.set(check(grade, request, grades.grades(sheetId.trim())));
    }

    /** The rate form's rules: the grade's rate as set by the request, or refused. */
    static RateValues check(String grade, RateRequest request, Collection<String> grades) throws InvalidRateException {
        String g = grade == null ? "" : grade.trim();
        if (!grades.contains(g)) {
            throw new InvalidRateException("Grade must be one of the sheet's grades");
        }
        String rate = request == null || request.rate() == null ? "" : request.rate().trim();
        if (!RATE.matcher(rate).matches()) {
            throw new InvalidRateException("The rate must be a percent 0.00 or more with up to two decimals");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidRateException("The to-date must not be before the from-date");
        }
        return new RateValues(g, new BigDecimal(rate).setScale(2), from, to,
                request.by() == null ? "" : request.by().trim());
    }

    private static LocalDate date(String value, String name) throws InvalidRateException {
        String text = value == null ? "" : value.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidRateException("The " + name + "-date must be a date yyyy-MM-dd");
        }
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Sets the grade's rate from its from-date on the sheet, replacing any rate it had for that from-date. */
public class SaveRate {
    public void save(@PathVariable("sheetId") String sheetId, @Val RateValues values, RateRepository rates,
            Out<Rate> rate) {
        rate.set(rates.save(new Rate(sheetId.trim(), values.grade(), values.rate(), values.from(), values.to())));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes RATE_SET to the audit file once the rate is stored, ending with from=<date> when it has a from-date, then to=<date> when it has a to-date. Then writes the
 * figures the change moved (see Rollup). */
public class RecordRateSet {
    public void record(@Val Rate rate, @Val RateValues values, @Val RollupBefore before, Rollup rollup, Audit audit) {
        audit.record("RATE_SET sheet=" + rate.sheetId() + " by=" + values.by() + " grade=" + rate.grade()
                + " rate=" + rate.rate().toPlainString() + (rate.from() == null ? "" : " from=" + rate.from())
                + (rate.to() == null ? "" : " to=" + rate.to()));
        rollup.record(rate.sheetId(), values.by(), before);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;
