package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Withdraws the newest version of the grade's rate for the from-date; refused when there is no such rate. */
public class WithdrawRate {
    public void withdraw(@PathVariable("sheetId") String sheetId, @Val RateWithdrawValues values, RateRepository rates,
            Out<RateWithdrawn> withdrawn) throws InvalidRateException {
        String sheet = sheetId.trim();
        if (!rates.has(sheet, values.grade(), values.from())) {
            throw new InvalidRateException("There is no such rate to withdraw");
        }
        withdrawn.set(new RateWithdrawn(sheet, values.grade(), values.from(),
                rates.withdraw(sheet, values.grade(), values.from())));
    }
}
EOF
cat > $R/RecordRateWithdrawn.java <<'EOF'
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes RATE_WITHDRAWN to the audit file once the rate is withdrawn, ending with from=<date> when it has a from-date.
 *  Then writes the figures the change moved (see Rollup). */
public class RecordRateWithdrawn {
    public void record(@Val RateWithdrawn withdrawn, @Val RateWithdrawValues values, @Val RollupBefore before,
            Rollup rollup, Audit audit) {
        audit.record("RATE_WITHDRAWN sheet=" + withdrawn.sheetId() + " by=" + values.by() + " grade=" + withdrawn.grade()
                + (withdrawn.from() == null ? "" : " from=" + withdrawn.from()));
        rollup.record(withdrawn.sheetId(), values.by(), before);
    }
}
EOF
cat > $R/RespondWithRateWithdrawn.java <<'EOF'
package net.officefloor.hq.app.rate;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the rate that applies again for the from-date, or null when the rate is gone. */
public class RespondWithRateWithdrawn {
    public void respond(@Val RateWithdrawn withdrawn, RateRepository rates, ObjectResponse<RateResponse> response) {
        Rate rate = withdrawn.restored();
        response.send(rate == null ? null : RateResponse.from(rate, 0, rates.older(rate.sheetId(), rate.grade(), rate.from())));
    }
}
EOF
